style.css:
@-moz-document domain("notion.so"), domain("notion.site") {
/* fundo geral */
body {
    background-color: #fff5f7 !important;
}

/* páginas */
.notion-page-content {
    background-color: #ffffff !important;
    border-radius: 12px !important;
}

/* sidebar */
.notion-sidebar {
    background-color: #ffeef2 !important;
}

/* hover suave */
.notion-sidebar div:hover {
    background-color: #ffd6e0 !important;
}

/* textos */
.notion-page-content * {
    color: #4a2a35 !important;
}

/* títulos */
h1, h2, h3 {
    color: #d63384 !important;
}

/* botões */
button {
    border-radius: 10px !important;
}

/* seleção */
::selection {
    background: #ffc2d1 !important;
}
}
